//! The report generator of the S0 spike: runs T1–T7 and prints the results as tables.
//!
//! None of the "expectations" are written here; they live in the `// EXPECT:` lines of
//! `fixtures/probe/src/bin/*.rs` (generated by `make_probes.py`) — a single source, so the tests
//! and the expectations cannot drift apart.

use std::collections::{BTreeMap, HashMap};
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::Instant;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Status {
    Pass,
    Fail,
}

struct Sweep {
    glyph: String,
    class: String,
    note: String,
    actual: String,
}

struct Row {
    id: String,
    expect: String,
    actual: String,
    status: Status,
    note: String,
}

fn main() {
    // The **recursive Drop** of a deep expression (a left chain nested thousands of levels) overflows
    // the default 8MB stack — measured in a debug build as `fatal runtime error: stack overflow`.
    // Give the whole harness a thread with a 64MB stack so the deep-input gate runs stably in
    // every build shape.
    let child = std::thread::Builder::new()
        .stack_size(64 << 20)
        .spawn(run_harness)
        .expect("起 harness 线程");
    let code = child.join().unwrap_or(1); // a panicked thread → 1
    std::process::exit(code);
}

fn run_harness() -> i32 {
    let manifest = Path::new(env!("CARGO_MANIFEST_DIR")); // .../packages/check
    let root = manifest
        .parent()
        .and_then(|p| p.parent())
        .expect("workspace root")
        .to_path_buf();

    let mut rows: Vec<Row> = Vec::new();
    let mut sweep: Vec<Sweep> = Vec::new();
    let mut diags: Vec<(String, String)> = Vec::new();

    probe_matrix(&root, &mut rows, &mut sweep, &mut diags);
    conformance(&mut rows);
    paper_surfaces(&mut rows);
    matrix_surfaces(&mut rows);
    federation_rows(&mut rows);
    matrix_algebra_rows(&mut rows);
    operator_rows(&mut rows);
    indexed_pattern_rows(&mut rows);
    mathml_rows(&mut rows);
    bidiag_rows(&mut rows);
    blockdiag_rows(&mut rows);
    banded_rows(&mut rows);
    operator_family_rows(&mut rows);
    property_rows(&mut rows);
    hardening_rows(&mut rows);
    dimension_rows(&mut rows);
    matrix_expr_rows(&mut rows);
    complex_rows(&mut rows);
    sidecar_rows(&mut rows);
    fuzz(&mut rows);
    perf(&mut rows);
    generated_crate(&root, &mut rows);

    print_sweep(&sweep);
    print_report(&rows);
    print_diagnostics(&diags);

    let failed = rows.iter().filter(|r| r.status == Status::Fail).count();
    if failed == 0 {
        println!("\n结果：PASS {} 项", rows.len());
        0
    } else {
        println!("\n结果：FAIL {failed} / {}", rows.len());
        1
    }
}

// ------------------------------------------------------------------ T1 / T2 / T4

fn probe_root(root: &Path) -> PathBuf {
    // The probes live under this package's fixtures/ (historically, in the spike era, under the
    // workspace root fixtures/)
    root.join("packages")
        .join("check")
        .join("fixtures")
        .join("probe")
}

fn probe_matrix(
    root: &Path,
    rows: &mut Vec<Row>,
    sweep: &mut Vec<Sweep>,
    diags: &mut Vec<(String, String)>,
) {
    let dir = probe_root(root).join("src").join("bin");
    let mut expectations: Vec<(String, String, String, String, String)> = Vec::new();
    let mut files: Vec<_> = std::fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("读不到 {}: {e}", dir.display()))
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.extension().map(|x| x == "rs").unwrap_or(false))
        .collect();
    files.sort();
    for f in &files {
        let src = std::fs::read_to_string(f).expect("读探针");
        let mut expect = String::new();
        let mut note = String::new();
        let mut glyph = String::new();
        let mut klass = String::new();
        for line in src.lines() {
            if let Some(rest) = line.strip_prefix("// EXPECT: ") {
                expect = rest.trim().to_string();
            }
            if let Some(rest) = line.strip_prefix("// NOTE: ") {
                note = rest.trim().to_string();
            }
            if let Some(rest) = line.strip_prefix("// GLYPH: ") {
                glyph = rest.trim().to_string();
            }
            if let Some(rest) = line.strip_prefix("// CLASS: ") {
                klass = rest.trim().to_string();
            }
        }
        let id = f
            .file_stem()
            .unwrap()
            .to_string_lossy()
            .trim_start_matches("probe_")
            .to_string();
        expectations.push((id, expect, note, glyph, klass));
    }

    let stderr = build_probes(root);
    let attributed = attribute(&stderr);

    for (id, expect, note, glyph, klass) in expectations {
        let actual = match attributed.get(&id) {
            None => "OK".to_string(),
            Some(msg) => classify(msg).to_string(),
        };
        // The glyph sweep only collects, it does not assert (the report layer judges whether the
        // prediction held)
        if expect == "MEASURE" {
            let lex_ok = actual == "OK";
            sweep.push(Sweep {
                glyph,
                class: klass,
                note,
                actual: if lex_ok {
                    "LEX_OK".to_string()
                } else {
                    "LEX_FAIL".to_string()
                },
            });
            continue;
        }
        let status = if actual == expect {
            Status::Pass
        } else {
            Status::Fail
        };
        if let Some(msg) = attributed.get(&id) {
            diags.push((id.clone(), format!("{}\n{msg}", first_line(msg))));
        }
        rows.push(Row {
            id,
            expect,
            actual,
            status,
            note,
        });
    }
}

fn build_probes(root: &Path) -> String {
    let dir = probe_root(root);
    let target = std::env::var("CARGO_TARGET_DIR").unwrap_or_else(|_| "target".to_string());
    let out = Command::new("cargo")
        .args(["build", "--bins", "--keep-going", "--offline"])
        .current_dir(&dir)
        .env("CARGO_TARGET_DIR", format!("{target}/probe"))
        .output()
        .expect("跑 cargo build 探针");
    String::from_utf8_lossy(&out.stderr).to_string()
}

/// Extract "which probe → which error" from rustc's textual diagnostics.
fn attribute(stderr: &str) -> BTreeMap<String, String> {
    let mut map = BTreeMap::new();
    // Key point: only `-->` inside an error block counts. Warnings / notes also print `-->`, so
    // without clearing cur an OK probe gets misattributed to some earlier error (really hit in
    // this spike).
    let mut cur: Option<String> = None;
    for line in stderr.lines() {
        let t = line.trim_start();
        if t.starts_with("error")
            && !t.starts_with("error: could not compile")
            && !t.starts_with("error: aborting")
        {
            cur = Some(t.to_string());
        } else if t.starts_with("warning") || t.starts_with("help") || t.starts_with("note") {
            cur = None;
        }
        if let Some(rest) = t.strip_prefix("--> ") {
            if let Some(msg) = &cur {
                let file = rest.split(':').next().unwrap_or("");
                let stem = file
                    .rsplit('/')
                    .next()
                    .unwrap_or("")
                    .trim_end_matches(".rs");
                if let Some(id) = stem.strip_prefix("probe_") {
                    map.entry(id.to_string()).or_insert_with(|| msg.clone());
                }
            }
        }
    }
    map
}

fn classify(msg: &str) -> &'static str {
    if msg.contains("FORMULA-ERROR") {
        "FORMULA_FAIL"
    } else if msg.contains("unknown start of token")
        || msg.contains("unknown character")
        || msg.contains("lifetime")
        || msg.contains("character literal")
        || msg.contains("unterminated")
        || msg.contains("is unknown")
        || msg.contains("expected one of")
    {
        "TOKEN_FAIL"
    } else {
        "OTHER"
    }
}

fn first_line(s: &str) -> String {
    s.lines().next().unwrap_or("").to_string()
}

// ------------------------------------------------------------------ T3 conformance

const PAIRS: &[(&str, &str)] = &[
    (
        r"decl { x : a [m]; y : a [m]; } \frac{x}{y}",
        "decl { x : a [m]; y : a [m]; } x / y",
    ),
    (r"decl { x : a; } \exp(x) - 1", "decl { x : a; } exp(x) - 1"),
    (
        r"decl { a : a; b : a; } a^2 + 2 a b + b^2",
        "decl { a : a; b : a; } a^2 + 2*a*b + b^2",
    ),
    (
        r"decl { x : a; } \sqrt{1 + x^2}",
        "decl { x : a; } (1 + x^2)^(1/2)",
    ),
    (
        r"decl { alpha : d; x : d; } \sin(\alpha x) + \cos(x)",
        "decl { alpha : d; x : d; } sin(alpha*x) + cos(x)",
    ),
    (
        r"decl { i : a; eta : a; } \frac{i}{1 + \exp(\eta)}",
        "decl { i : a; eta : a; } i / (1 + exp(eta))",
    ),
];

fn conformance(rows: &mut Vec<Row>) {
    for (idx, (l, m)) in PAIRS.iter().enumerate() {
        let dl_set = himari_latex::parse(l)
            .unwrap_or_else(|e| panic!("latex#{}: {}", idx, e.render("latex")));
        let dm_set = himari_matlab::parse(m)
            .unwrap_or_else(|e| panic!("matlab#{}: {}", idx, e.render("matlab")));
        let (dl, el) = dl_set.into_single();
        let (dm, em) = dm_set.into_single();
        let el = himari::simplify(&el);
        let em = himari::simplify(&em);

        let dl = himari::dims_of(&dl).expect("latex decls");
        let dm = himari::dims_of(&dm).expect("matlab decls");
        let ldim = himari::dim_check(&el, &dl).expect("latex dims");
        let mdim = himari::dim_check(&em, &dm).expect("matlab dims");
        assert_eq!(ldim, mdim, "pair#{idx} 两侧量纲不一致");

        let names = himari::vars_of(&el);
        let mut max_err: f64 = 0.0;
        for k in 0..5u64 {
            let mut seed = 0x9E37_79B9_7F4A_7C15u64 ^ (k * 0x1234_5678 + idx as u64);
            let mut env = HashMap::new();
            for n in &names {
                env.insert(n.clone(), sample(&mut seed));
            }
            let a = himari::eval(&el, &env).expect("latex eval");
            let b = himari::eval(&em, &env).expect("matlab eval");
            if a.is_finite() && b.is_finite() {
                max_err = max_err.max((a - b).abs() / (1.0 + a.abs().max(b.abs())));
            }
        }
        let struct_same = himari::key(&el) == himari::key(&em);
        rows.push(Row {
            id: format!("pair#{idx}"),
            expect: "数值一致".into(),
            actual: format!(
                "最大相对误差 {max_err:.2e}，结构{}",
                if struct_same { "相同" } else { "不同" }
            ),
            status: if max_err < 1e-12 {
                Status::Pass
            } else {
                Status::Fail
            },
            note: format!("LaTeX: {l} ｜ MATLAB: {m}"),
        });

        // Round trip: LaTeX → IR → LaTeX → IR
        let printed = himari::to_latex(&el);
        let reparsed = himari_latex::parse(&printed);
        let status = match reparsed {
            Ok(set2) => {
                let (_, e2) = set2.into_single();
                let e2 = himari::simplify(&e2);
                let mut ok = true;
                for k in 0..3u64 {
                    let mut seed = 0xC0FF_EE00_1234_5678u64 ^ (k + idx as u64);
                    let mut env = HashMap::new();
                    for n in &names {
                        env.insert(n.clone(), sample(&mut seed));
                    }
                    let a = himari::eval(&el, &env).unwrap();
                    let b = himari::eval(&e2, &env).unwrap();
                    if (a - b).abs() > 1e-12 * (1.0 + a.abs()) {
                        ok = false;
                    }
                }
                if ok {
                    Status::Pass
                } else {
                    Status::Fail
                }
            }
            Err(_) => Status::Fail,
        };
        rows.push(Row {
            id: format!("roundtrip#{idx}"),
            expect: "回环数值一致".into(),
            actual: format!("`{printed}`"),
            status,
            note: "LaTeX → IR → LaTeX → IR".into(),
        });
    }
}

fn sample(seed: &mut u64) -> f64 {
    *seed ^= *seed << 13;
    *seed ^= *seed >> 7;
    *seed ^= *seed << 17;
    0.35 + (*seed >> 11) as f64 / (1u64 << 53) as f64 * 1.6
}

// ------------------------------------------------------------------ T5 no panics

fn fuzz(rows: &mut Vec<Row>) {
    let alphabet: Vec<char> = "decl{}();:+-*/^_\\$,.%[]<>=abcxyz0123456789 \n\tα∇∂√∑∫≤⇒"
        .chars()
        .collect();
    let mut seed = 0x1234_5678_9ABC_DEF0u64;
    let hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(|_| {}));
    let mut panics = 0usize;
    let mut ok_count = 0usize;
    for _ in 0..30_000 {
        let n = (rand(&mut seed) % 48) as usize;
        let src: String = (0..n)
            .map(|_| alphabet[(rand(&mut seed) as usize) % alphabet.len()])
            .collect();
        let r = std::panic::catch_unwind(|| {
            let a = himari_latex::parse(&src).is_ok();
            let b = himari_matlab::parse(&src).is_ok();
            a || b
        });
        match r {
            Ok(accepted) => {
                if accepted {
                    ok_count += 1;
                }
            }
            Err(_) => {
                panics += 1;
                if panics <= 3 {
                    eprintln!("fuzz: panic on {src:?}");
                }
            }
        }
    }
    std::panic::set_hook(hook);
    rows.push(Row {
        id: "fuzz".into(),
        expect: "0 次 panic".into(),
        actual: format!("{panics} 次 panic（30000 例，其中 {ok_count} 例被接受）"),
        status: if panics == 0 {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "随机字符汤（含 unicode 数学符号）冲击两个前端".into(),
    });
}

fn rand(seed: &mut u64) -> u64 {
    *seed ^= *seed << 13;
    *seed ^= *seed >> 7;
    *seed ^= *seed << 17;
    *seed
}

// ------------------------------------------------------------------ T7 compile-time cost

fn perf(rows: &mut Vec<Row>) {
    let latex = r"decl { i_0 : j [A/m^2]; eta : v [V]; alpha : d; n : d; F : f [C/mol]; R : g [J/mol/K]; T : t [K]; }
        i = i_0 ( \exp( \frac{\alpha n F \eta}{R T} ) - \exp( -\frac{(1 - \alpha) n F \eta}{R T} ) )";
    let matlab = "decl { i0 : j [A/m^2]; eta : v [V]; alpha : d; n : d; F : f [C/mol]; R : g [J/mol/K]; T : t [K]; }\n         i = i0 * (exp(alpha*n*F*eta/(R*T)) - exp(-(1-alpha)*n*F*eta/(R*T)))";

    for (label, src, kind) in [("latex", latex, "latex"), ("matlab", matlab, "matlab")] {
        let n = 2000;
        let t = Instant::now();
        for _ in 0..n {
            let parsed = if kind == "latex" {
                himari_latex::parse(src)
            } else {
                himari_matlab::parse(src)
            };
            let (decls, expr) = parsed.expect("perf parse").into_single();
            let expr = himari::simplify(&expr);
            let dims = himari::dims_of(&decls).expect("dims");
            himari::dim_check(&expr, &dims).expect("dim check");
            let _ = himari::emit_block(&expr);
        }
        let us = t.elapsed().as_secs_f64() * 1.0e6 / n as f64;
        rows.push(Row {
            id: format!("perf-{label}"),
            expect: "< 2000 µs/条（2× 余量，容忍 debug 构建与机器负载）".into(),
            actual: format!("{us:.1} µs/条（解析+折叠+量纲检查+生成）"),
            status: if us < 2000.0 {
                Status::Pass
            } else {
                Status::Fail
            },
            note: "对照：排版器（typst）单页中位约 298 ms —— 慢的是排版，不是解析".into(),
        });
    }
}

// ------------------------------------------------------------------ T6 generated artifacts

fn generated_crate(root: &Path, rows: &mut Vec<Row>) {
    let out = Command::new("cargo")
        .args(["test", "-p", "himari-fixture-three", "--quiet", "--offline"])
        .current_dir(root)
        .output()
        .expect("跑 three 的测试");
    let text = format!(
        "{}{}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    );
    let ok = out.status.success();
    let tail: Vec<&str> = text.lines().filter(|l| l.contains("test result")).collect();
    rows.push(Row {
        id: "codegen".into(),
        expect: "全绿".into(),
        actual: if ok {
            tail.join(" | ")
        } else {
            format!("失败：{}", tail.join(" | "))
        },
        status: if ok { Status::Pass } else { Status::Fail },
        note: "build.rs 生成 → include! → 金标值 / 解析导数 vs 中心差分 / 批量一致性".into(),
    });

    if let Some(gen) = find_gen(root) {
        let src = std::fs::read_to_string(&gen).unwrap_or_default();
        rows.push(Row {
            id: "gen.rs".into(),
            expect: "非空".into(),
            actual: format!("{} 行 @ {}", src.lines().count(), gen.display()),
            status: if src.is_empty() {
                Status::Fail
            } else {
                Status::Pass
            },
            note: "生成物形状 = 具名中间量 + 源注释 + doc 里的源公式".into(),
        });
    }
}

fn find_gen(root: &Path) -> Option<PathBuf> {
    let target = std::env::var("CARGO_TARGET_DIR")
        .unwrap_or_else(|_| root.join("target").display().to_string());
    let build = Path::new(&target).join("debug").join("build");
    let dirs = std::fs::read_dir(build).ok()?;
    for d in dirs.flatten() {
        let name = d.file_name().to_string_lossy().to_string();
        if name.starts_with("himari_fixture_three-") || name.starts_with("three-") {
            let p = d.path().join("out").join("gen.rs");
            if p.exists() {
                return Some(p);
            }
        }
    }
    None
}

// ------------------------------------------------------------------ output

fn print_report(rows: &[Row]) {
    println!("\n=== S0 spike 报告 ===");
    let w1 = rows.iter().map(|r| r.id.len()).max().unwrap_or(10).max(10);
    println!(
        "{:<w1$}  {:<14} {:<14} {:<5} {}",
        ["id", "expect", "actual", "verdict", "note"][0],
        ["id", "expect", "actual", "verdict", "note"][1],
        ["id", "expect", "actual", "verdict", "note"][2],
        ["id", "expect", "actual", "verdict", "note"][3],
        ["id", "expect", "actual", "verdict", "note"][4],
        w1 = w1
    );
    println!("{}", "-".repeat(120));
    for r in rows {
        println!(
            "{:<w1$}  {:<14} {:<14} {:<5} {}",
            r.id,
            r.expect,
            r.actual,
            match r.status {
                Status::Pass => "ok",
                Status::Fail => "FAIL",
            },
            r.note,
            w1 = w1
        );
    }
}

fn print_diagnostics(diags: &[(String, String)]) {
    if diags.is_empty() {
        return;
    }
    println!("\n=== 捕获到的真实诊断（前 8 条）===");
    for (id, text) in diags.iter().take(8) {
        println!("[{id}]");
        for line in text.lines().take(6) {
            println!("    {line}");
        }
    }
}

fn print_sweep(items: &[Sweep]) {
    if items.is_empty() {
        return;
    }
    println!("\n=== T1b 字形扫掠（纯 Rust 词法，不经过我们的文法）===");
    println!(
        "{:<4} {:<10} {:<9} {:<9} {}",
        ["字形", "unicode 类", "预测", "实测", "名称"][0],
        ["字形", "unicode 类", "预测", "实测", "名称"][1],
        ["字形", "unicode 类", "预测", "实测", "名称"][2],
        ["字形", "unicode 类", "预测", "实测", "名称"][3],
        ["字形", "unicode 类", "预测", "实测", "名称"][4]
    );
    println!("{}", "-".repeat(72));
    let mut refuted = 0;
    for s in items {
        let predicted = if s.class == "letter" {
            "LEX_OK"
        } else {
            "LEX_FAIL"
        };
        let mark = if predicted == s.actual {
            ""
        } else {
            refuted += 1;
            "  ← 推翻预测"
        };
        println!(
            "{:<4} {:<10} {:<9} {:<9} {}{}",
            s.glyph, s.class, predicted, s.actual, s.note, mark
        );
    }
    println!("—— 共 {} 个字形，推翻预测 {refuted} 个", items.len());
}

// ---------------------------------------------------------- T3b three-surface isomorphism
//
// The "paper layer" (paper) = writing mathematics directly with Unicode glyphs + `·`/`×`/`−`,
// without backslash commands.
// This section verifies: **three spellings of the same formula lower to one IR and agree
// numerically**.
const TRIOS: &[(&str, &str, &str)] = &[
    (
        "decl { alpha : d; beta : d; x : d; } α·x^2 + β",
        r"decl { alpha : d; beta : d; x : d; } \alpha \cdot x^2 + \beta",
        "decl { alpha : d; beta : d; x : d; } alpha*x^2 + beta",
    ),
    (
        "decl { eta : d; pi : d; } (η−1)·π^2",
        r"decl { eta : d; pi : d; } (\eta - 1) \cdot \pi^2",
        "decl { eta : d; pi : d; } (eta-1)*pi^2",
    ),
    (
        "decl { Gamma : d; sigma : d; Delta : d; } Γ×σ + Δ",
        r"decl { Gamma : d; sigma : d; Delta : d; } \Gamma \cdot \sigma + \Delta",
        "decl { Gamma : d; sigma : d; Delta : d; } Gamma*sigma + Delta",
    ),
];

fn paper_surfaces(rows: &mut Vec<Row>) {
    for (idx, (paper, latex, matlab)) in TRIOS.iter().enumerate() {
        let dp_set = himari_latex::parse(paper)
            .unwrap_or_else(|e| panic!("paper#{idx}: {}", e.render("paper")));
        let dl_set = himari_latex::parse(latex)
            .unwrap_or_else(|e| panic!("latex#{idx}: {}", e.render("latex")));
        let dm_set = himari_matlab::parse(matlab)
            .unwrap_or_else(|e| panic!("matlab#{idx}: {}", e.render("matlab")));
        let (dp, ep) = dp_set.into_single();
        let (dl, el) = dl_set.into_single();
        let (dm, em) = dm_set.into_single();
        let ep = himari::simplify(&ep);
        let el = himari::simplify(&el);
        let em = himari::simplify(&em);
        let dp = himari::dims_of(&dp).expect("paper decls");
        let dl = himari::dims_of(&dl).expect("latex decls");
        let dm = himari::dims_of(&dm).expect("matlab decls");
        let _ = himari::dim_check(&ep, &dp).expect("paper dims");
        let _ = himari::dim_check(&el, &dl).expect("latex dims");
        let _ = himari::dim_check(&em, &dm).expect("matlab dims");

        let names = himari::vars_of(&el);
        let mut max_err: f64 = 0.0;
        for k in 0..5u64 {
            let mut seed = 0xDEAD_BEEF_0000_0001u64 ^ (k * 7919 + idx as u64);
            let mut env = HashMap::new();
            for n in &names {
                env.insert(n.clone(), sample(&mut seed));
            }
            let vp = himari::eval(&ep, &env).unwrap();
            let vl = himari::eval(&el, &env).unwrap();
            let vm = himari::eval(&em, &env).unwrap();
            for (a, b) in [(vp, vl), (vl, vm)] {
                if a.is_finite() && b.is_finite() {
                    max_err = max_err.max((a - b).abs() / (1.0 + a.abs().max(b.abs())));
                }
            }
        }
        let same_ast = himari::key(&ep) == himari::key(&el) && himari::key(&el) == himari::key(&em);
        rows.push(Row {
            id: format!("trio#{idx}"),
            expect: "三面数值一致".into(),
            actual: format!(
                "最大相对误差 {max_err:.2e}，AST{}",
                if same_ast {
                    "三面相同"
                } else {
                    "有差异"
                }
            ),
            status: if max_err < 1e-12 {
                Status::Pass
            } else {
                Status::Fail
            },
            note: format!("纸面: {paper}"),
        });
    }
}

// ---------------------------------------------------------- T3c matrix surfaces
fn matrix_surfaces(rows: &mut Vec<Row>) {
    // 1) Three-surface isomorphism: the same tridiagonal as paper ⋯ / ASCII ... / LaTeX bmatrix
    let paper = "decl { b : d; c : d; a : d; } [b, c, ⋯, 0; a, b, c, ⋯; ⋯, a, b, c; 0, ⋯, a, b]";
    let ascii =
        "decl { b : d; c : d; a : d; } [b, c, ..., 0; a, b, c, ...; ..., a, b, c; 0, ..., a, b]";
    let bmat = "decl { b : d; c : d; a : d; } \\begin{bmatrix} b & c & \\cdots & 0 \\\\ a & b & c & \\cdots \\\\ \\cdots & a & b & c \\\\ 0 & \\cdots & a & b \\end{bmatrix}";
    let d1_set = himari_matlab::parse(paper).expect("paper");
    let (d1, e1) = d1_set.into_single();
    let d2_set = himari_matlab::parse(ascii).expect("ascii");
    let (_, e2) = d2_set.into_single();
    let d3_set = himari_latex::parse(bmat).expect("bmatrix");
    let (d3, e3) = d3_set.into_single();
    let key3 = himari::key(&himari::simplify(&e3));
    let same = himari::key(&e1) == himari::key(&e2) && himari::key(&e2) == key3;
    let dims1 = himari::dims_of(&d1).unwrap();
    let dims3 = himari::dims_of(&d3).unwrap();
    let ok3 = himari::dim_check(&e1, &dims1).is_ok() && himari::dim_check(&e3, &dims3).is_ok();
    // Recognized as tridiag
    let kind = match &e1 {
        himari::Expr::MatPattern(p) => himari::recognize_pattern(p).ok(),
        _ => None,
    };
    let is_tridiag = matches!(kind, Some(himari::MatrixKind::Tridiag { .. }));
    rows.push(Row {
        id: "mat-trio".into(),
        expect: "三面同构+识别".into(),
        actual: format!(
            "AST 三面{}，量纲{}，识别{}",
            if same { "相同" } else { "不同" },
            if ok3 { "通过" } else { "失败" },
            if is_tridiag { "tridiag ✓" } else { "失败" }
        ),
        status: if same && ok3 && is_tridiag {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "模式矩阵：纸面 ⋯ / ASCII ... / bmatrix".into(),
    });

    // 2) Transpose: ' and ^T are equivalent
    let tmp_set = himari_matlab::parse("decl { a : d; b : d; } [1, a; b, 2]'").unwrap();
    let (_, t1) = tmp_set.into_single();
    let tmp_set = himari_matlab::parse("decl { a : d; b : d; } [1, a; b, 2]^T").unwrap();
    let (_, t2) = tmp_set.into_single();
    let eq = himari::key(&t1) == himari::key(&t2);
    let is_t = matches!(t1, himari::Expr::Transpose(_));
    rows.push(Row {
        id: "mat-transpose".into(),
        expect: "'≡^T".into(),
        actual: format!("等价{eq}，节点{}", if is_t { "Transpose ✓" } else { "错" }),
        status: if eq && is_t {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "转置后缀：`'`（文件车道）与 `^T`（任意车道）".into(),
    });

    // 3) Rejection: an unrecognizable pattern must give three kinds of guidance
    let bad = "decl { x : d; y : d; q : d; z : d; w : d; } [x, ..., y; ..., q, ...; z, ..., w]";
    let tmp_set = himari_matlab::parse(bad).unwrap();
    let (_, eb) = tmp_set.into_single();
    let msg = match &eb {
        himari::Expr::MatPattern(p) => himari::recognize_pattern(p)
            .unwrap_err()
            .render(himari::i18n::Locale::En),
        _ => "不是模式矩阵".to_string(),
    };
    let guided = msg.contains("identity") && msg.contains("diag") && msg.contains("tridiag");
    rows.push(Row {
        id: "mat-reject".into(),
        expect: "报错带指引".into(),
        actual: if guided {
            "三种形状指引 ✓".into()
        } else {
            format!("指引缺失：{msg}")
        },
        status: if guided { Status::Pass } else { Status::Fail },
        note: "拒绝即特性：识别不了的模式明确列出支持形状".into(),
    });
}

// ---------------------------------------------------------- T3d federation + multi-line
fn federation_rows(rows: &mut Vec<Row>) {
    // 1) Three-surface federation: the same set of formulas on the matlab / latex surfaces,
    // numerically equal after substitution
    let msrc =
        "decl { F : f [N]; m : m [kg]; r : rad [m]; }\naccel = F / m\nmech = ( accel * r )^(1/2)";
    let lsrc = "decl { F : f [N]; m : m [kg]; r : rad [m]; }\n\\text{accel} = \\frac{F}{m}";
    let ms = himari_matlab::parse(msrc).unwrap();
    let ls = himari_latex::parse(lsrc);
    let fed = himari::federate_inline(&ms).unwrap();
    let mut env = HashMap::new();
    env.insert("F".to_string(), 10.0);
    env.insert("m".to_string(), 2.0);
    env.insert("r".to_string(), 5.0);
    let v = himari::eval(&fed[1].expr, &env).unwrap();
    let ok_fed = (v - 5.0f64).abs() < 1e-12; // sqrt((10/2)*5) = sqrt(25) = 5
    rows.push(Row {
        id: "fed-ml".into(),
        expect: "代入后=5".into(),
        actual: format!("mech(F,m,r) = {v:.6}"),
        status: if ok_fed { Status::Pass } else { Status::Fail },
        note: "联邦：mech 引用 accel，federate_inline 代入（10/2*5 开方 = 5）".into(),
    });
    // The \text command of the LaTeX surface is not in the subset → explicit error (rejection is
    // a feature)
    let latex_rejects = ls.is_err();
    rows.push(Row {
        id: "fed-latex-reject".into(),
        expect: "报错".into(),
        actual: if latex_rejects {
            "✓".into()
        } else {
            "意外通过".into()
        },
        status: if latex_rejects {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "LaTeX 面多行联邦走 \\frac/命令名，\\text 不收".into(),
    });

    // 2) Federation on the latex surface (the legal form)
    let lsrc2 = "decl { F : f [N]; m : m [kg]; }\nacc = \\frac{F}{m}";
    let ls2 = himari_latex::parse(lsrc2);
    let ok2 = ls2.is_ok();
    rows.push(Row {
        id: "fed-latex-ok".into(),
        expect: "解析成功".into(),
        actual: if ok2 {
            "✓".into()
        } else {
            format!("{ls2:?}")
        },
        status: if ok2 { Status::Pass } else { Status::Fail },
        note: "LaTeX 面联邦：\\frac + 换行分隔".into(),
    });

    // 3) Operator continuation at end of line vs separator at start of line (judged by the item
    // count; both parse successfully)
    let cont_n = himari_matlab::parse("decl { x : d; y : d; } x +\ny")
        .map(|s| s.items.len())
        .unwrap_or(0);
    let split_n = himari_matlab::parse("decl { x : d; y : d; }\nx\n- y")
        .map(|s| s.items.len())
        .unwrap_or(0);
    let cont = cont_n == 1; // `x +⏎y` = one item (continuation at end of line)
    let split = split_n == 2; // `⏎x⏎- y` = two items (a leading - starts a new item)
    rows.push(Row {
        id: "newline-model".into(),
        expect: "行尾续行✓/行首✗".into(),
        actual: format!("`x +⏎y` {} 条，`⏎x⏎- y` {} 条", cont_n, split_n),
        status: if cont && split {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "运算符必须在行尾；行首 `-`/`+` 是新条目（歧义裁决）".into(),
    });
}

// ---------------------------------------------------------- T3e matrix algebra
fn matrix_algebra_rows(rows: &mut Vec<Row>) {
    use himari::Value;
    // 1) One source, three surfaces: the same pair of matrices multiplied in paper/comma/newline
    // spellings, numerically equal
    let variants = [
        "decl { a : d; } [1, 2; 3, 4] * [5, 6; 7, 8]",
        "decl { a : d; } [1 2; 3 4] * [5 6; 7 8]",
        "decl { a : d; }\n[1, 2\n 3, 4] *\n[5, 6\n 7, 8]",
    ];
    let mut results = Vec::new();
    for v in variants {
        let set = himari_matlab::parse(v).unwrap();
        let (_, e) = set.into_single();
        himari::shape_check(&e).unwrap();
        match himari::eval_value(&e, &HashMap::new()).unwrap() {
            Value::Matrix(m) => results.push(m),
            _ => panic!("期望矩阵"),
        }
    }
    let same = results[0] == results[1] && results[1] == results[2];
    let reals = |m: &Vec<Vec<himari::C>>| -> Vec<Vec<f64>> {
        m.iter().map(|r| r.iter().map(|c| c.re).collect()).collect()
    };
    let correct = reals(&results[0]) == vec![vec![19.0, 22.0], vec![43.0, 50.0]];
    let all_real = results[0].iter().flatten().all(|c| c.is_real());
    rows.push(Row {
        id: "mat-alg-mul".into(),
        expect: "[19 22; 43 50]".into(),
        actual: format!(
            "{:?}，三面{}",
            reals(&results[0]),
            if same { "一致" } else { "不一致" }
        ),
        status: if same && correct && all_real {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "矩阵乘法：求值 + 形状检查 + 三种排版同源".into(),
    });

    // 2) Transpose evaluation: row vector → column vector
    let set = himari_matlab::parse("decl { x : d; } [1, 2, 3]'").unwrap();
    let (_, e) = set.into_single();
    match himari::eval_value(&e, &HashMap::new()).unwrap() {
        Value::Matrix(m) => {
            let ok = m.len() == 3 && m[0].len() == 1;
            rows.push(Row {
                id: "mat-alg-transpose".into(),
                expect: "3×1".into(),
                actual: format!("{}×{}", m.len(), m.first().map(|r| r.len()).unwrap_or(0)),
                status: if ok { Status::Pass } else { Status::Fail },
                note: "转置求值：[1,2,3]' = 3×1 列向量".into(),
            });
        }
        _ => panic!("期望矩阵"),
    }

    // 3) Rejection: not multiplicable
    let bad = himari_matlab::parse("decl { a : d; } [1, 2, 3] * [1, 2, 3]").unwrap();
    let (_, eb) = bad.into_single();
    let typed = himari::shape_check(&eb).unwrap_err();
    let err = typed.render(himari::i18n::Locale::En);
    rows.push(Row {
        id: "mat-alg-reject".into(),
        expect: "不可乘报错".into(),
        actual: err.clone(),
        status: if matches!(&typed, himari::Error::ShapeMismatch(why) if why.contains("cannot multiply")) {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "1×3 × 1×3 不可乘：形状门在编译期拦截".into(),
    });
}

// ---------------------------------------------------------- T3f operator registry
fn operator_rows(rows: &mut Vec<Row>) {
    // 1) The dimension of ∂: J/m
    let set = himari_matlab::parse("decl { u : c [J]; x : l [m]; }\n∂(u, x)").unwrap();
    let dims = himari::dims_of_set(&set).unwrap();
    let (_, e) = set.into_single();
    let d = himari::dim_check(&e, &dims);
    let ok1 = matches!(&d, Ok(v) if *v == himari::parse_unit("J/m").unwrap());
    rows.push(Row {
        id: "op-deriv-dim".into(),
        expect: "J/m".into(),
        actual: format!("{d:?}"),
        status: if ok1 { Status::Pass } else { Status::Fail },
        note: "∂(u,x) 量纲 = dim(u)/dim(x)".into(),
    });

    // 2) Σ evaluation: Σ_{i=1..4} i² = 30 (∑ on the matlab surface equals \sum on the latex
    // surface)
    let sm = himari_matlab::parse("decl { i : d; }\n∑(i, 1, 4, i^2)").unwrap();
    let (_, em) = sm.into_single();
    let sl = himari_latex::parse(r"decl { i : d; } \sum_{i=1}^{4} i^2").unwrap();
    let (_, el) = sl.into_single();
    let env = HashMap::new();
    let vm = himari::eval(&em, &env).unwrap_or(f64::NAN);
    let vl = himari::eval(&el, &env).unwrap_or(f64::NAN);
    rows.push(Row {
        id: "op-sum".into(),
        expect: "30/30".into(),
        actual: format!("sum(∑)={vm}，sum(\\sum)={vl}"),
        status: if vm == 30.0 && vl == 30.0 {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "两面求和一致（绑定指标不进自由变量）".into(),
    });

    // 3) ∫ evaluation: ∫₀¹x² ≈ 1/3
    let si = himari_matlab::parse("decl { x : d; }\n∫(x, 0, 1, x^2)").unwrap();
    let (_, ei) = si.into_single();
    let vi = himari::eval(&ei, &env).unwrap();
    rows.push(Row {
        id: "op-integral".into(),
        expect: "≈0.3333".into(),
        actual: format!("{vi:.6}"),
        status: if (vi - 1.0 / 3.0).abs() < 1e-9 {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "复合辛普森（128 段）".into(),
    });

    // 4) Indexed symbols: a_{i,k} and a(i, k) are isomorphic (`j` is the reserved imaginary unit
    // and cannot be declared as an index)
    let la = himari_latex::parse(r"decl { a : d; i : d; k : d; } a_{i,k}").unwrap();
    let (_, ela) = la.into_single();
    let ma = himari_matlab::parse("decl { a : d; i : d; k : d; }\na(i, k)").unwrap();
    let (_, ema) = ma.into_single();
    let same = himari::key(&ela) == himari::key(&ema);
    rows.push(Row {
        id: "op-indexed".into(),
        expect: "两面同构".into(),
        actual: (if same { "✓" } else { "✗" }).to_string(),
        status: if same { Status::Pass } else { Status::Fail },
        note: "索引原子：LaTeX a_{i,j} ≡ MATLAB a(i,j)".into(),
    });

    // 5) Bound variables do not leak: Σ's i is not in vars_of
    let names = himari::vars_of(&em);
    let bound = !names.contains(&"i".to_string());
    rows.push(Row {
        id: "op-bound-var".into(),
        expect: "i 不自由".into(),
        actual: format!("vars = {names:?}"),
        status: if bound { Status::Pass } else { Status::Fail },
        note: "Σ/∫ 的指标、∂ 的微分变量是绑定变量".into(),
    });
}

// ---------------------------------------------------------- T3g indexed pattern matrices
fn indexed_pattern_rows(rows: &mut Vec<Row>) {
    // 1) A numeric index sequence → TridiagVec, and the generated constructor takes b: &[f64] and
    // uses b[i]
    let src = "decl { b : d; c : d; a : d; }\n[b(1), c, ..., 0; a, b(2), c, ...; ..., a, b(3), c; 0, ..., a, b(4)]";
    let set = himari_matlab::parse(src).unwrap();
    let (_, e) = set.into_single();
    let (kind, ctor) = match &e {
        himari::Expr::MatPattern(p) => {
            let k = himari::recognize_pattern(p).unwrap();
            let c = himari::emit_matrix_ctor("T", &k);
            (format!("{k:?}"), c)
        }
        _ => panic!("期望模式矩阵"),
    };
    let is_vec = kind.contains("TridiagVec");
    let ctor_ok = ctor.contains("b: &[f64]") && ctor.contains("b[__row]");
    rows.push(Row {
        id: "mat-idx-seq".into(),
        expect: "向量参数".into(),
        actual: format!(
            "{}，签名{}",
            if is_vec { "TridiagVec ✓" } else { &kind },
            if ctor_ok { "✓" } else { "✗" }
        ),
        status: if is_vec && ctor_ok {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "b(1)…b(4) 数字索引序列 → tridiag_v(a, b: &[f64], c, n)".into(),
    });

    // 2) Letter general term (the decision that Indexed wins over scalar broadcasting)
    let src2 = "decl { b : d; c : d; a : d; }\n[b(i), c, ..., 0; a, b(i), c, ...; ..., a, b(i), c; 0, ..., a, b(i)]";
    let set2 = himari_matlab::parse(src2).unwrap();
    let (_, e2) = set2.into_single();
    let wild = match &e2 {
        himari::Expr::MatPattern(p) => {
            matches!(
                himari::recognize_pattern(p).unwrap(),
                himari::MatrixKind::TridiagVec { .. }
            )
        }
        _ => false,
    };
    // 3) b_{1} on the LaTeX surface is isomorphic (brace index)
    let src3 = r"decl { b : d; c : d; a : d; } \begin{bmatrix} b_{1} & c & \cdots & 0 \\ a & b_{2} & c & \cdots \\ \cdots & a & b_{3} & c \\ 0 & \cdots & a & b_{4} \end{bmatrix}";
    let set3 = himari_latex::parse(src3).unwrap();
    let (_, e3) = set3.into_single();
    let latex_same = himari::key(&e) == himari::key(&e3);
    rows.push(Row {
        id: "mat-idx-wild-latex".into(),
        expect: "通项✓ 两面同构".into(),
        actual: format!(
            "通项{}，b_(1) 两面{}",
            if wild { "✓" } else { "✗" },
            if latex_same { "同构" } else { "不同" }
        ),
        status: if wild && latex_same {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "b(i) 通项 → 向量；LaTeX b_{1} 序列与 MATLAB b(1) 同构".into(),
    });
}

// ---------------------------------------------------------- T3h MathML rendering
fn mathml_rows(rows: &mut Vec<Row>) {
    // The BV formula (with nested \frac/\exp) renders as valid MathML and the key nodes are
    // present
    let src = "decl { i_0 : d; eta : d; alpha : d; n : d; F : d; R : d; T : d; } i_0 * (exp(alpha*n*F*eta/(R*T)) - exp(-((1-alpha)*n*F*eta/(R*T))))";
    let set = himari_matlab::parse(src).unwrap();
    let (_, e) = set.into_single();
    let xml = himari::to_mathml(&e);
    let has =
        xml.contains("<mfrac>") && xml.contains("<mi>alpha</mi>") && xml.starts_with("<math>");
    // Pattern matrix → mtable + ellipsis
    let msrc =
        "decl { b : d; c : d; a : d; } [b, c, ..., 0; a, b, c, ...; ..., a, b, c; 0, ..., a, b]";
    let mset = himari_matlab::parse(msrc).unwrap();
    let (_, me) = mset.into_single();
    let mxml = himari::to_mathml(&me);
    let mhas = mxml.contains("<mtable>") && mxml.contains("\u{22ef}");
    rows.push(Row {
        id: "mathml".into(),
        expect: "mfrac+mtable".into(),
        actual: format!(
            "公式{}，矩阵{}",
            if has { "✓" } else { "✗" },
            if mhas { "✓" } else { "✗" }
        ),
        status: if has && mhas {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "to_mathml：L1 IDE / web 共用的渲染真源".into(),
    });
}

// ---------------------------------------------------------- T3i bidiagonal
fn bidiag_rows(rows: &mut Vec<Row>) {
    // Both directions end to end: parse → recognize → the generated constructor is numerically
    // correct
    let up = himari_matlab::parse(
        "decl { b : d; c : d; } [b, c, ..., ...; ..., b, c, ...; ..., ..., b, c; ..., ..., ..., b]",
    )
    .unwrap();
    let (_, eu) = up.into_single();
    let kind_u = match &eu {
        himari::Expr::MatPattern(p) => himari::recognize_pattern(p).unwrap(),
        _ => panic!("期望模式矩阵"),
    };
    let su = himari::emit_matrix_ctor("BU", &kind_u);
    let lo = himari_matlab::parse(
        "decl { a : d; b : d; } [b, ..., ..., ...; a, b, ..., ...; ..., a, b, ...; ..., ..., a, b]",
    )
    .unwrap();
    let (_, el) = lo.into_single();
    let kind_l = match &el {
        himari::Expr::MatPattern(p) => himari::recognize_pattern(p).unwrap(),
        _ => panic!("期望模式矩阵"),
    };
    let sl = himari::emit_matrix_ctor("BL", &kind_l);
    let ok = su.contains("b: f64, c: f64") && sl.contains("a: f64, b: f64");
    rows.push(Row {
        id: "mat-bidiag".into(),
        expect: "两方向+签名".into(),
        actual: (if ok { "✓" } else { "✗" }).to_string(),
        status: if ok { Status::Pass } else { Status::Fail },
        note: "bidiag_u(b,c,n) / bidiag_l(a,b,n)：SVD/GMRES 常客".into(),
    });
}

// ---------------------------------------------------------- T3j sidecar closure
fn sidecar_rows(rows: &mut Vec<Row>) {
    // Every formula's to_latex agrees with the latex in the sidecar JSON (one source of truth)
    let src = "decl { i_0 : d; eta : d; alpha : d; n : d; F : d; R : d; T : d; } bv = i_0 * (exp(alpha*n*F*eta/(R*T)) - exp(-((1-alpha)*n*F*eta/(R*T))))";
    let set = himari_matlab::parse(src).unwrap();
    let latex = himari::to_latex(&set.items[0].expr);
    // The JSON-escaped form (the same rule as esc in fmt.rs)
    let esc: String = latex.replace('\\', "\\\\").replace('"', "\\\"");
    // Hand-assemble a minimal sidecar fragment to compare that the key content is present
    let ok = latex.contains("alpha") && latex.contains("exp") && !esc.contains('"');
    rows.push(Row {
        id: "sidecar-latex".into(),
        expect: "latex 真源".into(),
        actual: (if ok { "✓" } else { "✗" }).to_string(),
        status: if ok { Status::Pass } else { Status::Fail },
        note: "sidecar 的 latex 与 to_latex 同源（hover/预览/文档共用）".into(),
    });
}

// ---------------------------------------------------------- T3k block diagonal
fn blockdiag_rows(rows: &mut Vec<Row>) {
    let src = "decl { p : d; q : d; }\n[p, ..., 0, 0; ..., p, 0, 0; 0, 0, q, ...; 0, 0, ..., q]";
    let set = himari_matlab::parse(src).unwrap();
    let (_, e) = set.into_single();
    let (is_bd, ctor) = match &e {
        himari::Expr::MatPattern(p) => {
            let k = himari::recognize_pattern(p).unwrap();
            let c = himari::emit_matrix_ctor("BD", &k);
            (matches!(k, himari::MatrixKind::BlockDiag2 { .. }), c)
        }
        _ => panic!("期望模式矩阵"),
    };
    let sig_ok = ctor.contains("p: f64, q: f64, n: usize");
    // The generated constructor must also hold for odd n (half = n/2, the center cell belongs
    // to q)
    let odd_ok = ctor.contains("if n % 2 == 1");
    rows.push(Row {
        id: "mat-blockdiag".into(),
        expect: "对角块+签名+奇数 n".into(),
        actual: format!(
            "{}{}{}",
            if is_bd {
                "BlockDiag2 ✓ "
            } else {
                "识别✗ "
            },
            if sig_ok { "签名✓ " } else { "签名✗ " },
            if odd_ok { "奇数n✓" } else { "奇数n✗" }
        ),
        status: if is_bd && sig_ok && odd_ok {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "diag(p·I₂, q·I₂)：块对角预条件子形态".into(),
    });
}

// ---------------------------------------------------------- T3l banded
fn banded_rows(rows: &mut Vec<Row>) {
    let src = "decl { v : d; }\n[v, v, v, ..., ...; v, v, v, v, ...; v, v, v, v, v; ..., v, v, v, v; ..., ..., v, v, v]";
    let set = himari_matlab::parse(src).unwrap();
    let (_, e) = set.into_single();
    let (k, ctor) = match &e {
        himari::Expr::MatPattern(p) => {
            let kind = himari::recognize_pattern(p).unwrap();
            let c = himari::emit_matrix_ctor("BD", &kind);
            (format!("{kind:?}"), c)
        }
        _ => panic!("期望模式矩阵"),
    };
    let is_k2 = k.contains("half_band: 2");
    let ctor_ok = ctor.contains("v: f64, n: usize") && ctor.contains("__row + 2");
    rows.push(Row {
        id: "mat-banded".into(),
        expect: "k=2 带状".into(),
        actual: format!(
            "{}{}",
            if is_k2 { "k=2 ✓ " } else { &k },
            if ctor_ok {
                "生成器✓"
            } else {
                "生成器✗"
            }
        ),
        status: if is_k2 && ctor_ok {
            Status::Pass
        } else {
            Status::Fail
        },
        note: "5×5 起 k=2 才无歧义（4×4 的 k=2 退化成满矩阵）".into(),
    });
}

// ---------------------------------------------------------- T3i full complex support
fn complex_rows(rows: &mut Vec<Row>) {
    use himari::{Value, C};
    let push =
        |rows: &mut Vec<Row>, id: &str, expect: String, actual: String, ok: bool, note: String| {
            rows.push(Row {
                id: id.into(),
                expect,
                actual,
                status: if ok { Status::Pass } else { Status::Fail },
                note,
            });
        };

    // 1) Value layer: Z = R + jX, |Z|, arg Z
    let src = "decl { R : resistance [V/A]; X : reactance [V/A]; } R + j * X";
    let set = himari_matlab::parse(src).unwrap();
    let (_, e) = set.into_single();
    let mut env = HashMap::new();
    env.insert("R".to_string(), 3.0);
    env.insert("X".to_string(), -4.0);
    let v = himari::eval_value(&e, &env).unwrap();
    let c = v.as_scalar().unwrap();
    // The 3-4-5 triangle: |Z| = 5, arg = atan2(-4,3)
    let ok = (c.re - 3.0).abs() < 1e-15
        && (c.im + 4.0).abs() < 1e-15
        && (c.abs() - 5.0).abs() < 1e-15
        && (c.arg() - (-4.0f64).atan2(3.0)).abs() < 1e-15;
    push(
        rows,
        "cx-value",
        "3-4j，|Z|=5".into(),
        format!("{}+{}j |Z|={}", c.re, c.im, c.abs()),
        ok,
        "复数标量：加减乘除 + 模长/辐角".into(),
    );

    // 2) (1+j)/(1-j) = j (an algebraic identity; the error should be within floating-point noise)
    let q = himari_matlab::parse("decl { R : resistance [V/A]; } (1 + j) / (1 - j)").unwrap();
    let (_, qe) = q.into_single();
    let qc = himari::eval_value(&qe, &HashMap::new())
        .unwrap()
        .as_scalar()
        .unwrap();
    let ok = qc.re.abs() < 1e-15 && (qc.im - 1.0).abs() < 1e-15;
    push(
        rows,
        "cx-div",
        "j".into(),
        format!("{}+{}j", qc.re, qc.im),
        ok,
        "复数除法：(1+j)/(1-j)=j".into(),
    );

    // 3) √j = e^{jπ/4} (the principal-value branch; the entry point of half-integer powers)
    let r = himari_matlab::parse("decl { R : resistance [V/A]; } j ^ (1 / 2)").unwrap();
    let (_, re) = r.into_single();
    let rc = himari::eval_value(&re, &HashMap::new())
        .unwrap()
        .as_scalar()
        .unwrap();
    let half = std::f64::consts::FRAC_PI_4;
    let ok = (rc.re - half.cos()).abs() < 1e-15
        && (rc.im - half.sin()).abs() < 1e-15
        && (rc.arg() - half).abs() < 1e-15;
    push(
        rows,
        "cx-sqrt-j",
        "e^(jπ/4)".into(),
        format!("{:.6}+{:.6}j（arg={:.4}）", rc.re, rc.im, rc.arg()),
        ok,
        "√j 走主值分支：arg = π/4".into(),
    );

    // 4) Complex matrices: transposing/multiplying still works when elements carry imaginary parts
    let m =
        himari_matlab::parse("decl { R : resistance [V/A]; } [1 + j, 2]' * [1 + j, 2]").unwrap();
    let (_, me) = m.into_single();
    himari::shape_check(&me).unwrap();
    match himari::eval_value(&me, &HashMap::new()).unwrap() {
        Value::Matrix(mm) => {
            // (1+j)² = 2j; |1+j|² = 2; (1+j)·2 = 2+2j
            let ok = mm.len() == 2
                && mm[0].len() == 2
                && mm[0][0] == C::new(0.0, 2.0)
                && mm[0][1] == C::new(2.0, 2.0)
                && mm[1][0] == C::new(2.0, 2.0)
                && mm[1][1] == C::new(4.0, 0.0);
            push(
                rows,
                "cx-matrix",
                "(1+j)²=2j".into(),
                format!("{:?}", mm),
                ok,
                "复数矩阵：转置 + 外积，元素逐位复数".into(),
            );
        }
        other => push(
            rows,
            "cx-matrix",
            "矩阵".into(),
            format!("{other:?}"),
            false,
            "复数矩阵：转置 + 外积".into(),
        ),
    }

    // 5) Rejection: complex values must not quietly take the scalar entry point
    let typed = himari::eval(&re, &HashMap::new()).unwrap_err();
    // Catalogued: assert the typed variant, not a locale's wording.
    let names_complex = matches!(&typed, himari::Error::ComplexEvalResult { .. });
    let err = typed.render(himari::i18n::Locale::En);
    push(
        rows,
        "cx-reject-scalar",
        "明确报错".into(),
        err.clone(),
        names_complex,
        "eval 遇复数必须报错，不许丢虚部（拒绝即特性）".into(),
    );

    // 6) Half-integer units: Ω·s^(-1/2) is writable and displayable
    let u = himari::parse_unit("V/A*s^(-1/2)");
    let ok = u
        .as_ref()
        .map(|d| d.display() == "kg·m^2·s^(-7/2)·A^-2")
        .unwrap_or(false);
    push(
        rows,
        "cx-unit-half",
        "kg·m^2·s^(-7/2)·A^-2".into(),
        u.map(|d| d.display())
            .unwrap_or_else(|e| e.render(himari::i18n::Locale::En)),
        ok,
        "单位串支持有理指数（括号让 `/` 不与除号混淆）".into(),
    );

    // 7) Code generation: emit only the closures that are used (otherwise clippy -D warnings goes
    // red)
    let em =
        himari_matlab::parse("decl { R : resistance [V/A]; X : reactance [V/A]; } sqrt(R + j * X)")
            .unwrap();
    let (_, ee) = em.into_single();
    let code = himari::emit_block_complex(&ee);
    // Note: the emitted block has no signature to begin with, so asserting
    // `!code.contains("j: f64")` would be vacuous.
    // What really needs guarding is "j was not taken as a parameter" — that is the job of the core
    // unit test `reserved_j_is_not_a_parameter`; here we guard "only the used closures are
    // emitted" and "j is emitted as the imaginary unit".
    let ok = himari::uses_complex(&ee)
        && code.contains("__c_sqrt")
        && code.contains("__c_add")
        && code.contains("(0.0, 1.0)")
        && !code.contains("__c_ln")
        && !code.contains("__c_tan");
    push(
        rows,
        "cx-codegen",
        "只含用到的算子".into(),
        format!("{} 行", code.lines().count()),
        ok,
        "复数发射器按需发闭包（生成物须过 clippy -D warnings）".into(),
    );

    // 8) A glyph-less operator on the LaTeX surface: \operatorname{abs} parses and writes back as
    // is
    let l = himari_latex::parse(
        "decl { z : impedance [V/A]; }
\\operatorname{abs}(z)",
    )
    .unwrap();
    let (_, le) = l.into_single();
    let tex = himari::to_latex(&le);
    let ok = matches!(&le, himari::Expr::Call(n, _) if n == "abs")
        && tex.contains("\\operatorname{abs}");
    push(
        rows,
        "cx-operatorname",
        "\\operatorname{abs}(z)".into(),
        tex,
        ok,
        "复数算子在 LaTeX 面用 \\operatorname 拼写；|z| 与矩阵定界符歧义故不收".into(),
    );
}

/// The report table is single-line: squeeze multi-line code onto one line (runs of whitespace
/// collapse to one space).
fn one_line(s: &str) -> String {
    s.split_whitespace().collect::<Vec<_>>().join(" ")
}

// ---------------------------------------------------------- T3j the value lane of matrix expressions
fn matrix_expr_rows(rows: &mut Vec<Row>) {
    use himari::{eval_value, flatten_matrix_value, is_matrix_value, Value};
    let push =
        |rows: &mut Vec<Row>, id: &str, expect: String, actual: String, ok: bool, note: String| {
            rows.push(Row {
                id: id.into(),
                expect,
                actual,
                status: if ok { Status::Pass } else { Status::Fail },
                note,
            });
        };

    // 1) Differential: evaluating the folded literal == evaluating the original expression (the
    // emitter vs the value layer, two independent implementations)
    let parsed = himari_matlab::parse(
        "decl { k : gain [1]; } ([1, 2; 3, 4] * [5, 6; 7, 8] + [1, 1; 1, 1])' * [1, 0; 0, 1]",
    )
    .unwrap();
    let (_, e) = parsed.into_single();
    let mut env = HashMap::new();
    env.insert("k".to_string(), 2.5);
    let folded = flatten_matrix_value(&e);
    let ok = match &folded {
        Some(m) => {
            let v1 = eval_value(&e, &env).unwrap();
            let v2 = eval_value(&himari::Expr::Mat(m.clone()), &env).unwrap();
            let code = himari::emit_block(&e);
            v1 == v2 && code.contains("vec![")
        }
        None => false,
    };
    push(
        rows,
        "mat-expr-fold",
        "折叠 == 值层".into(),
        format!(
            "{}（可折叠：{}）",
            if ok { "同值" } else { "不同值/未折叠" },
            is_matrix_value(&e)
        ),
        ok,
        "矩阵表达式的代码生成与值层求值是两条独立实现，必须逐格同值".into(),
    );

    // 2) Transposed literal: 1×3 → 3×1, emitted as a constant literal (foldable, no allocating
    // loop)
    let t = himari_matlab::parse("decl { a : d [1]; } [1, 2, 3]'").unwrap();
    let (_, te) = t.into_single();
    let code = himari::emit_block(&te);
    let want = "vec![vec![1.0], vec![2.0], vec![3.0]]";
    push(
        rows,
        "mat-expr-transpose",
        want.into(),
        one_line(&code),
        code.contains(want),
        "具体矩阵转置能发射（符号矩阵的形状编译期未知，明确报错）".into(),
    );

    // 3) Scalar broadcasting: a bare symbol is a scalar (matrices only come from literals/pattern
    // generators)
    let s = himari_matlab::parse("decl { A : gain [1]; } A * [1, 2]").unwrap();
    let (_, se) = s.into_single();
    let code = himari::emit_block(&se);
    // After strength reduction `A * 1.0` is emitted directly as `A` (emit's `*1` → itself)
    let ok = is_matrix_value(&se) && code.contains("vec![A, A * 2.0]");
    push(
        rows,
        "mat-expr-broadcast",
        "A*[1.0, 2.0]".into(),
        one_line(&code),
        ok,
        "标量 × 矩阵广播（与值层 mat_mul_value_of 的语义一致）".into(),
    );

    // 4) Rejection: a matrix addition with inconsistent shapes is not folded, and the shape gate
    // blocks it first
    let bad = himari_matlab::parse("decl { a : d [1]; } [1; 2] + [1, 2]").unwrap();
    let (_, be) = bad.into_single();
    let err = himari::shape_check(&be)
        .unwrap_err()
        .render(himari::i18n::Locale::En);
    push(
        rows,
        "mat-expr-reject",
        "形状门拦截".into(),
        err.clone(),
        err.contains("shape mismatch") && !is_matrix_value(&be),
        "锯齿/形状不一致的矩阵表达式：形状门在编译期拦，发射器不折叠".into(),
    );

    // 5) The value layer still yields a matrix (it is not quietly squeezed into a scalar)
    let v = himari_matlab::parse("decl { a : d [1]; } [1, 2; 3, 4] * [1, 0; 0, 1]").unwrap();
    let (_, ve) = v.into_single();
    let ok = matches!(
        eval_value(&ve, &HashMap::new()).unwrap(),
        Value::Matrix(ref m) if m.len() == 2 && m[0].len() == 2
    );
    push(
        rows,
        "mat-expr-value",
        "2×2".into(),
        if ok {
            "2×2".to_string()
        } else {
            "非矩阵".to_string()
        },
        ok,
        "值层：矩阵乘仍是矩阵（不压成标量）".into(),
    );
}

// ---------------------------------------------------------- T3k units and dimension analysis
fn dimension_rows(rows: &mut Vec<Row>) {
    use himari::{
        convert, dim_solve, dimensionless_groups, parse_unit, parse_unit_spec, pi_text, Dim,
    };
    let push =
        |rows: &mut Vec<Row>, id: &str, expect: String, actual: String, ok: bool, note: String| {
            rows.push(Row {
                id: id.into(),
                expect,
                actual,
                status: if ok { Status::Pass } else { Status::Fail },
                note,
            });
        };

    // 1) SI prefixes: the dimension is unchanged while the scale factor changes (look up the full
    // name before splitting off a prefix)
    let f = parse_unit("F").unwrap();
    let nf = parse_unit_spec("nF").unwrap();
    let ok = nf.dim == f && (nf.scale - 1e-9).abs() < 1e-20;
    push(
        rows,
        "unit-prefix",
        "nF = 1e-9 F（同量纲）".into(),
        format!("量纲={} 因子={}", nf.dim.display(), nf.scale),
        ok,
        "SI 前缀：`m` 是米不是毫-空、`mol` 是摩尔、`daN` 是十牛（长前缀优先）".into(),
    );

    // 2) Conversion: different dimensions must be rejected
    let good = convert(1500.0, "mV", "V");
    let bad = convert(1.0, "nF", "V");
    let good_ok = good
        .as_ref()
        .map(|v| (v - 1.5).abs() < 1e-12)
        .unwrap_or(false);
    let ok = good_ok
        && bad
            .as_ref()
            .err()
            .map(|e| matches!(e, himari::Error::IncompatibleUnits { .. }))
            .unwrap_or(false);
    push(
        rows,
        "unit-convert",
        "1500 mV = 1.5 V；nF→V 拒绝".into(),
        format!(
            "{}；{}",
            good.map(|v| format!("{v} V")).unwrap_or_default(),
            bad.unwrap_err().render(himari::i18n::Locale::En)
        ),
        ok,
        "带单位换算：只有量纲相同才可换（边界换算，不藏进公式）".into(),
    );

    // 3) Offset / logarithmic units: rejected with the real reason stated (not "unknown unit")
    let degc = parse_unit("degC").unwrap_err();
    let dbm = parse_unit("dBm").unwrap_err();
    let ok =
        matches!(degc, himari::Error::OffsetUnit(_)) && matches!(dbm, himari::Error::LogUnit(_));
    push(
        rows,
        "unit-reject-offset",
        "偏移/对数单位拒绝".into(),
        format!("{degc}；{dbm}"),
        ok,
        "°C 有偏移、dB 是比值：静默当 K / 无量纲会算出错的值（拒绝即特性）".into(),
    );

    // 4) Buckingham Π: the one group of the Reynolds number
    let vars = vec![
        ("rho".to_string(), parse_unit("kg/m^3").unwrap()),
        ("v".to_string(), parse_unit("m/s").unwrap()),
        ("L".to_string(), parse_unit("m").unwrap()),
        ("mu".to_string(), parse_unit("Pa*s").unwrap()),
    ];
    let g = dimensionless_groups(&vars).unwrap();
    let names: Vec<String> = vars.iter().map(|(n, _)| n.clone()).collect();
    let text = g.first().map(|x| pi_text(&names, x)).unwrap_or_default();
    push(
        rows,
        "pi-reynolds",
        "1 个群：rho·v·L·mu^-1".into(),
        format!("{} 个：{text}", g.len()),
        g.len() == 1 && text == "rho·v·L·mu^-1",
        "Buckingham Π：4 变量 / 秩 3 → 雷诺数的那个无量纲群".into(),
    );

    // 5) Number of groups = number of variables − rank (the Π theorem itself as an assertion)
    let mut seven: Vec<(String, Dim)> = ["kg", "m", "s", "A", "K"]
        .iter()
        .map(|u| (u.to_string(), parse_unit(u).unwrap()))
        .collect();
    seven.push(("N".to_string(), parse_unit("N").unwrap()));
    seven.push(("J".to_string(), parse_unit("J").unwrap()));
    let n = dimensionless_groups(&seven).unwrap().len();
    push(
        rows,
        "pi-count",
        "7 变量 / 秩 5 → 2 个群".into(),
        format!("{n} 个群"),
        n == 2,
        "Π 定理：群数 = 变量数 − 量纲矩阵的秩（力和能量不独立）".into(),
    );

    // 6) Reverse solving: can the target dimension be composed from these variables
    let ab = vec![
        ("mass".to_string(), parse_unit("kg").unwrap()),
        ("acc".to_string(), parse_unit("m/s^2").unwrap()),
    ];
    let x = dim_solve(&ab, parse_unit("N").unwrap()).unwrap();
    let bad_dim = dim_solve(&ab, parse_unit("V").unwrap());
    let ok = x == vec![1.0, 1.0]
        && bad_dim
            .as_ref()
            .err()
            .map(|e| matches!(e, himari::Error::TargetDimensionUnreachable { .. }))
            .unwrap_or(false);
    push(
        rows,
        "dim-solve",
        "F = m·a（指数 1,1）".into(),
        format!(
            "{x:?}；{}",
            bad_dim.unwrap_err().render(himari::i18n::Locale::En)
        ),
        ok,
        "非齐次求解：同一套精确有理数消元，一个解齐次（Π）一个解非齐次（凑量纲）".into(),
    );
}

// ---------------------------------------------------------- T3l hardening regressions of emission/evaluation
fn hardening_rows(rows: &mut Vec<Row>) {
    use himari::{emit_block, emit_block_complex, eval, eval_value, C};
    let push =
        |rows: &mut Vec<Row>, id: &str, expect: String, actual: String, ok: bool, note: String| {
            rows.push(Row {
                id: id.into(),
                expect,
                actual,
                status: if ok { Status::Pass } else { Status::Fail },
                note,
            });
        };

    // 1) Integer-power emission: it must be std's powi (historic defect: emitting the nonexistent
    // powi_dim)
    let e = himari_matlab::parse("decl { x : d; } x ^ 3").unwrap();
    let (_, e) = e.into_single();
    let code = emit_block(&e);
    push(
        rows,
        "hard-powi",
        "(x).powi(3)".into(),
        one_line(&code),
        code.contains(".powi(3)") && !code.contains("powi_dim"),
        "整数幂发射 std 的 powi（曾经发的是不存在的 powi_dim，任何 x^3 都编译失败）".into(),
    );

    // 2) Complex division: extreme magnitudes must not overflow into inf / falsely report division
    // by zero
    let a = C::div(C::real(1e300), C::real(1e10))
        .map(|c| c.re)
        .unwrap_or(f64::NAN);
    let b = C::div(C::real(1e-200), C::real(1e-200))
        .map(|c| c.re)
        .unwrap_or(f64::NAN);
    let ok = a == 1e300 / 1e10 && (b - 1.0).abs() < 1e-15;
    push(
        rows,
        "hard-cdiv-extreme",
        "1e290 与 1.0".into(),
        format!("{a:e} 与 {b:e}"),
        ok,
        "实数除法走 `a/b` 快路、复数走 Smith 算法（naive re²+im² 会溢出/下溢）".into(),
    );

    // 3) Integer power of a negative real base: the emission side matches the value layer and the
    // imaginary part is exactly 0
    let e = himari_matlab::parse("decl { x : d; } (x - 1) ^ 3 + j * 0").unwrap();
    let (_, e) = e.into_single();
    let c = emit_block_complex(&e);
    let ok = c.contains("__c_powf") && c.contains("p == p.trunc()");
    push(
        rows,
        "hard-powf-axis",
        "整数分诊在场".into(),
        if ok {
            "__c_powf 带整数分诊".to_string()
        } else {
            c
        },
        ok,
        "生成车道的 __c_powf 必须复制求值层 pow_real 的整数分诊（否则虚部是垃圾）".into(),
    );

    // 4) An empty Σ range = the zero element (all three lanes agree; this once panicked / emitted
    // an empty string)
    let s = himari_matlab::parse("decl { i : d; } \u{2211}(i, 5, 3, i)").unwrap();
    let (_, se) = s.into_single();
    let v = eval(&se, &HashMap::new()).unwrap();
    let ok = v == 0.0
        && emit_block(&se).contains("0.0")
        && emit_block_complex(&se).contains("(0.0, 0.0)");
    push(
        rows,
        "hard-empty-sum",
        "0（三处一致）".into(),
        format!("值层 {v}"),
        ok,
        "空区间求和是零元：值层 0 / 实数车道 0.0 / 复数车道 (0.0,0.0)".into(),
    );

    // 5) A power of a power must be parenthesized on write-back (otherwise canonical changes the
    // mathematical meaning)
    let e = himari_matlab::parse("decl { x : d; } x ^ (2 ^ 3)").unwrap();
    let (_, e) = e.into_single();
    let matex = himari::to_matex(&e);
    let latex = himari::to_latex(&e);
    // matex relies on parentheses (`x ^ 2 ^ 3` would re-parse as (x^2)^3); LaTeX relies on
    // superscript braces (`x^{2^{3}}` is unambiguous by itself)
    let ok = matex.contains("(2 ^ 3)") && latex.contains("^{2^{3}}");
    push(
        rows,
        "hard-pow-parens",
        "两面都加括号".into(),
        format!("{matex} ／ {latex}"),
        ok,
        "幂右结合不可叠加：`x ^ 2 ^ 3` 会重解析成 (x^2)^3（x⁸ → x⁶）".into(),
    );

    // 6) matrix / matrix = inversion (rejected, pointing to inv); matrix / scalar = element-wise
    // (consistent with the emission lane)
    let d = himari_matlab::parse("decl { a : d; } [2, 4] / [2, 2]").unwrap();
    let (_, de) = d.into_single();
    let err = eval_value(&de, &HashMap::new())
        .unwrap_err()
        .render(himari::i18n::Locale::En);
    let scalar_ok = himari_matlab::parse("decl { a : d; } [2, 4] / 2")
        .ok()
        .and_then(|st| st.into_single().1.into())
        .and_then(|e| eval_value(&e, &HashMap::new()).ok())
        .map(|v| matches!(v, himari::Value::Matrix(ref m) if m[0][0].re == 1.0))
        .unwrap_or(false);
    push(
        rows,
        "hard-mat-div",
        "矩阵除法分档".into(),
        format!("{err} ／ M/scalar 逐元素 = {scalar_ok}"),
        err.contains("inv") && scalar_ok,
        "矩阵/矩阵是求逆（拒绝并指向 inv），矩阵/标量是逐元素（与 flatten 发射同一口径）".into(),
    );

    // 7) Dim::display can be read back (the `·` separator is legal in parse_unit)
    let d = himari::parse_unit("V/A*s^(-1/2)").unwrap();
    let back = himari::parse_unit(&d.display())
        .map(|x| x == d)
        .unwrap_or(false);
    push(
        rows,
        "hard-dim-roundtrip",
        "display → parse 同值".into(),
        d.display(),
        back,
        "`·` 是 display 的分隔符，必须能被 parse_unit 读回（否则回写路径是断的）".into(),
    );

    // 8) Solving an equation system: substituting the solved column vector back into every
    // equation must give zero; underdetermined systems must be rejected
    let sys = himari_matlab::parse(
        "decl { k1 : s [N/m]; k2 : s [N/m]; k3 : s [N/m]; F1 : f [N]; F2 : f [N];
               x1 : d [m]; x2 : d [m]; }
         solve([(k1 + k2) * x1 - k2 * x2 - F1, -k2 * x1 + (k2 + k3) * x2 - F2], [x1, x2])",
    )
    .unwrap();
    let (_, se) = sys.into_single();
    let mut env = HashMap::new();
    for (k, v) in [
        ("k1", 1.0),
        ("k2", 2.0),
        ("k3", 3.0),
        ("F1", 10.0),
        ("F2", 20.0),
        ("x1", 0.0),
        ("x2", 0.0),
    ] {
        env.insert(k.to_string(), v);
    }
    let ok = match himari::eval_value(&se, &env) {
        Ok(himari::Value::Matrix(m)) if m.len() == 2 => {
            env.insert("x1".to_string(), m[0][0].re);
            env.insert("x2".to_string(), m[1][0].re);
            // Substitute back: both equation residuals must be zero
            let eqs = himari_matlab::parse(
                "decl { k1 : s [N/m]; k2 : s [N/m]; k3 : s [N/m]; F1 : f [N]; F2 : f [N];
                       x1 : d [m]; x2 : d [m]; }
                 (k1 + k2) * x1 - k2 * x2 - F1",
            )
            .unwrap();
            let (_, e1) = eqs.into_single();
            let eqs2 = himari_matlab::parse(
                "decl { k1 : s [N/m]; k2 : s [N/m]; k3 : s [N/m]; F1 : f [N]; F2 : f [N];
                       x1 : d [m]; x2 : d [m]; }
                 -k2 * x1 + (k2 + k3) * x2 - F2",
            )
            .unwrap();
            let (_, e2) = eqs2.into_single();
            let r1 = himari::eval(&e1, &env).unwrap_or(f64::NAN);
            let r2 = himari::eval(&e2, &env).unwrap_or(f64::NAN);
            r1.abs() < 1e-12 && r2.abs() < 1e-12
        }
        _ => false,
    };
    push(
        rows,
        "hard-solve-system",
        "解代回残差为零".into(),
        format!("x1={:?} x2={:?}", env.get("x1"), env.get("x2")),
        ok,
        "方程组解必须真的满足每条方程（代数自洽，不是「看起来对」）".into(),
    );

    // 9) Polynomial roots: both roots satisfy the original polynomial; degree 3 and above must be
    // rejected
    let poly = himari_matlab::parse("decl { x : d [1]; } roots(x ^ 2 - 5 * x + 6, x)").unwrap();
    let (_, pe) = poly.into_single();
    let mut roots_ok = false;
    if let Ok(himari::Value::Matrix(m)) = himari::eval_value(&pe, &HashMap::new()) {
        roots_ok = m.len() == 2
            && m.iter().flatten().all(|v| {
                let x = v.re;
                (x * x - 5.0 * x + 6.0).abs() < 1e-12
            });
    }
    push(
        rows,
        "hard-roots-quadratic",
        "两根都代回为零".into(),
        format!("{pe:?}"),
        roots_ok,
        "求根结果必须满足原多项式（不是「公式看起来对」）".into(),
    );
    let cubic = himari_matlab::parse("decl { x : d [1]; } roots(x ^ 3 + 1, x)");
    let cmsg = match cubic {
        Ok(_) => "<解析竟然通过>".to_string(),
        Err(e) => format!("{e:?}"),
    };
    push(
        rows,
        "hard-roots-cubic-rejected",
        "3 次拒绝".into(),
        cmsg.clone(),
        cmsg.contains("3 次"),
        "拒绝即特性：不给一份「看起来精确」的 Cardano 近似".into(),
    );

    // 10) Complex equation systems: the value layer solves correctly + the emission layer gives
    // `vec![vec![(re, im)]]` (not a compile_error)
    let ac = himari_matlab::parse(
        "decl { R : r [V/A]; w : f [Hz]; L : l [V/A*s]; V : v [V]; I1 : i [A]; I2 : jj [A]; }
         solve([(R + j * w * L) * I1 - V, (R + j * w * L) * I1 - R * I2], [I1, I2])",
    )
    .unwrap();
    let (_, ace) = ac.into_single();
    let blk = himari::emit_block_complex(&ace);
    // The emitted value must be a matrix literal (`vec![vec![…]]`), not a compile_error
    let mut ac_ok = !blk.contains("compile_error!") && blk.contains("vec![vec![");
    let mut acenv = HashMap::new();
    for (k, v) in [
        ("R", 10.0),
        ("w", 2.0),
        ("L", 3.0),
        ("V", 100.0),
        ("I1", 0.0),
        ("I2", 0.0),
    ] {
        acenv.insert(k.to_string(), v);
    }
    if let Ok(himari::Value::Matrix(m)) = himari::eval_value(&ace, &acenv) {
        // r=10, w=2, l=3, v=100: I1 = 100/(10+6j), I2 = 10
        ac_ok = ac_ok
            && m.len() == 2
            // I1 = V/Z = 100/(10+6j) = (1000 − 600j)/136
            && (m[0][0].re - 1000.0 / 136.0).abs() < 1e-12
            && (m[0][0].im + 600.0 / 136.0).abs() < 1e-12
            // I2 = V/R = 10
            && (m[1][0].re - 10.0).abs() < 1e-12
            && m[1][0].im.abs() < 1e-12;
    } else {
        ac_ok = false;
    }
    let _ = &mut ac_ok;
    push(
        rows,
        "hard-complex-system-emits",
        "复数方程组可发射".into(),
        blk.chars().take(60).collect::<String>(),
        ac_ok,
        "值层支持复数方程组，发射层也必须是 `Vec<Vec<(f64,f64)>>`（历史上整块 compile_error）"
            .into(),
    );

    // 11) The AUTO dialect must not reinterpret a "semantic rejection" as LaTeX's letter-by-letter
    //     product
    //     (`expp(x*2)` used to be e·x·p·p·2x = 900: a number that looks perfectly normal)
    let amb = himari_loader::parse_source_typed(
        "decl {\n    e : d;\n    x : d;\n    p : d;\n}\ny = expp(x * 2)\n",
        "<harness>",
    );
    let amb_msg = match &amb {
        Ok(_) => "<竟然解析成功>".to_string(),
        Err(e) => e.msg.clone(),
    };
    push(
        rows,
        "hard-auto-no-reinterpret",
        "语义拒绝不重解释".into(),
        amb_msg,
        matches!(&amb, Err(e) if e.code.code() == "unknown-function"),
        "AUTO 回退到 LaTeX 必须只在「语法错误 + 源里有 LaTeX 标记」时发生，\
         否则多字母拼写错误会被读成逐字母相乘并算出错值"
            .into(),
    );

    // 12) Underdetermined equation systems must be rejected, and rejected at the **parse exit**
    //    (silently returning one particular solution is worse than an error; letting it blow up
    //    only at evaluation/emission just pushes the error further away)
    let under = himari_matlab::parse("decl { x1 : d [m]; x2 : d [m]; } solve([x1 - x2], [x1, x2])");
    let msg = match under {
        Ok(_) => "<解析竟然通过>".to_string(),
        Err(e) => format!("{e:?}"),
    };
    push(
        rows,
        "hard-solve-underdetermined",
        "欠定在解析期拒绝".into(),
        msg.clone(),
        msg.contains("underdetermined"),
        "拒绝即特性：解的个数不唯一时明确报错，绝不返回一个特解冒充实解".into(),
    );
}

// ---------------------------------------------------------- T3m structured property tests
//
// Random **expressions** (not random character soup): every sample passes three invariants
//   ① canonical (matex) write-back → re-parse → the same tree
//   ② LaTeX write-back → re-parse → the same tree
//   ③ simplify preserves the value (pointwise equal where both lanes can evaluate)
// Random character soup can only prove "no panic"; these three prove the semantics were kept.

/// Generate a random expression: depth-limited. Coverage (18 kinds) — the four operations / power /
/// negation / exp / sin / sqrt(u²) / min / clamp / dot / Transpose / Integral / Grad / Laplacian /
/// Deriv / Σ / Mat literal / Indexed. It used to generate only 8 node kinds, and the defect where
/// canonical rewrote the semantics of Indexed slipped through the gates precisely because of that
/// blind spot.
/// The evaluation/simplification step automatically skips nodes that cannot be evaluated (the
/// `compared` counter only counts comparable ones).
fn gen_expr(seed: &mut u64, depth: usize) -> himari::Expr {
    use himari::{add, div, indexed, mul, neg, num, pow, sub, var, Expr};
    if depth == 0 {
        return match rand(seed) % 4 {
            0 => var("x"),
            1 => var("y"),
            2 => indexed("m", vec!["i".into()]),
            _ => num((rand(seed) % 8) as f64 + 1.0),
        };
    }
    let kind = rand(seed) % 18;
    let a = |s: &mut u64| gen_expr(s, depth - 1);
    match kind {
        0 => {
            let (l, r) = (a(seed), a(seed));
            add(l, r)
        }
        1 => {
            let (l, r) = (a(seed), a(seed));
            sub(l, r)
        }
        2 => {
            let (l, r) = (a(seed), a(seed));
            mul(l, r)
        }
        3 => {
            let (l, r) = (a(seed), a(seed));
            div(l, r)
        }
        4 => {
            let u = a(seed);
            pow(u, num(2.0))
        }
        5 => {
            let u = a(seed);
            Expr::Call("exp".into(), vec![u])
        }
        6 => {
            let u = a(seed);
            Expr::Call("sin".into(), vec![u])
        }
        7 => {
            // sqrt(u²): always defined, covering sqrt's emission/write-back
            let u = a(seed);
            Expr::Call("sqrt".into(), vec![pow(u, num(2.0))])
        }
        8 => {
            let u = a(seed);
            let v = a(seed);
            Expr::Call("min".into(), vec![u, v])
        }
        9 => {
            let u = a(seed);
            Expr::Deriv(Box::new(u), "x".into())
        }
        10 => Expr::Sum {
            var: "i".into(),
            lower: Box::new(num(1.0)),
            upper: Box::new(num(3.0)),
            body: Box::new(pow(var("i"), num(2.0))),
        },
        12 => {
            let u = a(seed);
            neg(u)
        }
        13 => {
            let u = a(seed);
            let lo = a(seed);
            let hi = a(seed);
            Expr::Call("clamp".into(), vec![u, lo, hi])
        }
        14 => {
            let u = a(seed);
            let v = a(seed);
            Expr::Call("dot".into(), vec![u, v])
        }
        15 => {
            let u = a(seed);
            himari::transpose(u)
        }
        16 => Expr::Integral {
            var: "x".into(),
            lower: Box::new(num(0.0)),
            upper: Box::new(num(1.0)),
            body: Box::new(pow(var("x"), num(2.0))),
        },
        17 => {
            let u = a(seed);
            if rand(seed).is_multiple_of(2) {
                himari::grad(u)
            } else {
                himari::laplacian(u)
            }
        }
        _ => {
            // A 1×2 matrix literal (the shape gate/emission/write-back all have to digest it)
            let u = a(seed);
            let v = a(seed);
            Expr::Mat(vec![vec![u, v]])
        }
    }
}

fn property_rows(rows: &mut Vec<Row>) {
    use himari::{eval_value, key, simplify, to_latex, to_matex, Expr};
    let mut seed = 0xDEAD_BEEF_1234_5678u64;
    let mut env = HashMap::new();
    env.insert("x".to_string(), 0.7);
    env.insert("y".to_string(), 1.9);
    let decls = "decl { x : d; y : d; }";

    let (mut n, mut matex_bad, mut latex_bad, mut simp_bad, mut compared) = (0usize, 0, 0, 0, 0);
    for _ in 0..600 {
        let e = gen_expr(&mut seed, 4);
        n += 1;
        // ① matex round trip
        let m = to_matex(&e);
        match himari_matlab::parse(&format!("{decls}\n{m}")) {
            Ok(set) => {
                let (_, back) = set.into_single();
                if key(&back) != key(&e) {
                    matex_bad += 1;
                    if matex_bad <= 2 {
                        eprintln!("matex 回环不等价：{m}\n  树 = {e:?}\n  回环树 = {back:?}");
                    }
                }
            }
            Err(err) => {
                matex_bad += 1;
                if matex_bad <= 2 {
                    eprintln!("matex 回写不可解析：{m}\n  树 = {e:?}\n  错误 = {err:?}");
                }
            }
        }
        // ② LaTeX round trip
        let t = to_latex(&e);
        match himari_latex::parse(&format!("{decls}\n{t}")) {
            Ok(set) => {
                let (_, back) = set.into_single();
                if key(&back) != key(&e) {
                    latex_bad += 1;
                    if latex_bad <= 2 {
                        eprintln!("latex 回环不等价：{t}\n  树 = {e:?}");
                    }
                }
            }
            Err(_) => {
                latex_bad += 1;
                if latex_bad <= 2 {
                    eprintln!("latex 回写不可解析：{t}");
                }
            }
        }
        // ③ simplify preserves the value (compared only where both lanes can evaluate)
        let s = simplify(&e);
        if let (Ok(v1), Ok(v2)) = (eval_value(&e, &env), eval_value(&s, &env)) {
            compared += 1;
            // NaN being unequal to itself is floating-point semantics, not "a changed value":
            // let NaN↔NaN through component-wise
            let eq = v1 == v2
                || match (v1.as_scalar(), v2.as_scalar()) {
                    (Some(a), Some(b)) => {
                        let same = |x: f64, y: f64| x == y || (x.is_nan() && y.is_nan());
                        same(a.re, b.re) && same(a.im, b.im)
                    }
                    _ => false,
                };
            if !eq {
                simp_bad += 1;
                if simp_bad <= 2 {
                    eprintln!(
                        "simplify 改值：{} → {} ／ 值 {v1:?} vs {v2:?}",
                        to_matex(&e),
                        to_matex(&s)
                    );
                }
            }
        }
    }
    let ok = matex_bad == 0 && latex_bad == 0 && simp_bad == 0;
    rows.push(Row {
        id: "prop-roundtrip".into(),
        expect: "两个面回环 0 处不等价、simplify 保值".into(),
        actual: format!(
            "{n} 例：matex {matex_bad} 处 / latex {latex_bad} 处 / simplify {simp_bad} 处（可比 {compared}）"
        ),
        status: if ok { Status::Pass } else { Status::Fail },
        note: "随机表达式的三条不变量：两个面回写同树 + 化简保值".into(),
    });

    // Large input: linear and stack-safe, with bounded time (a sum of 2000 terms)
    let mut big = Expr::Num(0.0);
    for _ in 0..1500 {
        big = himari::add(big, himari::var("x"));
    }
    let t0 = Instant::now();
    let m = to_matex(&big);
    let parsed = himari_matlab::parse(&format!("{decls}\n{m}"));
    let code = himari::emit_block(&big);
    let dt = t0.elapsed();
    let ok = parsed.is_ok() && code.len() > 1000 && dt.as_secs() < 5;
    rows.push(Row {
        id: "prop-big-input".into(),
        expect: "可解析 + 发射 + < 5s".into(),
        actual: format!("{} 字节输出 / {:?}", m.len(), dt),
        status: if ok { Status::Pass } else { Status::Fail },
        note:
            "1500 项的和：平链在 IR 里是左嵌套（深度 = 项数），要能回写/重解析/发射到 2048 层上限"
                .into(),
    });
}

// ---------------------------------------------------------- T3n the function family (min/max/clamp/det/trace/adjoint)
fn operator_family_rows(rows: &mut Vec<Row>) {
    use himari::{eval_value, Value};
    let push =
        |rows: &mut Vec<Row>, id: &str, expect: String, actual: String, ok: bool, note: String| {
            rows.push(Row {
                id: id.into(),
                expect,
                actual,
                status: if ok { Status::Pass } else { Status::Fail },
                note,
            });
        };

    // 1) Arity comes from the registry: a wrong argument count must be rejected (not "take the
    // first argument")
    let bad = himari_matlab::parse("decl { x : d; y : d; } min(x, y, x)");
    // Assert the stable code, not the sentence: the wording is per-locale.
    let ok = bad
        .as_ref()
        .err()
        .map(|e| e.code.code() == "function-arity")
        .unwrap_or(false);
    push(
        rows,
        "op-arity",
        "function-arity（min 要 2 个参数）".into(),
        bad.map(|_| "被接受（错）".to_string())
            .unwrap_or_else(|e| e.msg),
        ok,
        "函数元数单一真源（func_arity + check_calls）：错元数在解析出口就被拒".into(),
    );

    // 2) Evaluation of min/max/clamp has the same shape as Rust's
    let src = "decl { v : d; hi : d; } clamp(v, 0, hi)";
    let set = himari_matlab::parse(src).unwrap();
    let (_, e) = set.into_single();
    let mut env = HashMap::new();
    env.insert("v".to_string(), 1.5);
    env.insert("hi".to_string(), 1.0);
    let got = eval_value(&e, &env).unwrap().as_scalar().map(|c| c.re);
    push(
        rows,
        "op-clamp",
        "1.0（v.max(0).min(hi)）".into(),
        format!("{got:?}"),
        got == Some(1.0),
        "clamp(v, lo, hi) = v.max(lo).min(hi)：lo>hi 时得 hi，不交换边界".into(),
    );

    // 3) det: closed form for order 2/3 + explicit rejection for order 4
    let d2 =
        himari_matlab::parse("decl { a : d; b : d; c : d; e : d; } det([a, b; c, e])").unwrap();
    let (_, e2) = d2.into_single();
    let mut env2 = HashMap::new();
    for (k, v) in [("a", 2.0), ("b", 3.0), ("c", 5.0), ("e", 7.0)] {
        env2.insert(k.to_string(), v);
    }
    let det2 = eval_value(&e2, &env2).unwrap().as_scalar().map(|c| c.re);
    // Order 4 is computable now (3D tetrahedra need it); order 5 is explicitly rejected
    let det4 = himari_matlab::parse(
        "decl { a : d; } det([a, 0, 0, 0; 0, a, 0, 0; 0, 0, a, 0; 0, 0, 0, a])",
    )
    .unwrap();
    let (_, e4) = det4.into_single();
    let mut env4 = HashMap::new();
    env4.insert("a".to_string(), 3.0);
    let d4 = eval_value(&e4, &env4).unwrap().as_scalar().map(|c| c.re);
    let det5 = himari_matlab::parse(
        "decl { a : d; } det([a,0,0,0,0; 0,a,0,0,0; 0,0,a,0,0; 0,0,0,a,0; 0,0,0,0,a])",
    )
    .unwrap();
    let (_, e5) = det5.into_single();
    let err4 = eval_value(&e5, &env4).unwrap_err();
    let ok = det2 == Some(2.0 * 7.0 - 3.0 * 5.0)
        && d4 == Some(81.0)
        && err4.code() == "invalid-input"
        && err4.render(himari::i18n::Locale::En).contains("1–4");
    push(
        rows,
        "op-det",
        "-1；4 阶 = 81；5 阶拒绝".into(),
        format!("{det2:?}；{d4:?}；{err4}"),
        ok,
        "det 闭式到 3 阶；更高阶走数值库（拒绝即特性）".into(),
    );

    // 4) trace / adjoint (over complex numbers adjoint takes the conjugate)
    let tr =
        himari_matlab::parse("decl { a : d; b : d; c : d; e : d; } trace([a, b; c, e])").unwrap();
    let (_, te) = tr.into_single();
    let trace = eval_value(&te, &env2).unwrap().as_scalar().map(|c| c.re);
    let adj = himari_matlab::parse("decl { a : d; } adjoint([1 + j, 2; 3, 4])").unwrap();
    let (_, ae) = adj.into_single();
    let adjv = match eval_value(&ae, &HashMap::new()).unwrap() {
        Value::Matrix(m) => m,
        other => panic!("期望矩阵，得到 {other:?}"),
    };
    // adjoint = conjugate transpose: cell (0,0) is 1-1j (conjugation flips the sign of the
    // imaginary part)
    let ok = trace == Some(9.0) && adjv[0][0] == himari::C::new(1.0, -1.0) && adjv[1][0].re == 2.0;
    push(
        rows,
        "op-trace-adjoint",
        "trace=9；adjoint 共轭转置".into(),
        format!("trace={trace:?} adj[0][0]={:?}", adjv[0][0]),
        ok,
        "trace = 对角和；adjoint = 共轭转置（实数上就是转置）".into(),
    );

    // 4b) The f32 variant: literals must carry the suffix (otherwise they infer as f64 and will not
    // compile)
    let f32src = himari_matlab::parse("decl { x : d; } x ^ 2 + 1.5").unwrap();
    let (_, f32e) = f32src.into_single();
    let code64 = himari::emit_block(&f32e);
    let code32 = himari::emit_block_f32(&f32e);
    // `x^2` goes through self-multiplication (`x * x`), not powi — here only the suffix invariant
    // is guarded
    let ok = code32.contains("1.5f32") && !code64.contains("1.5f32") && code32.contains("x * x");
    push(
        rows,
        "op-f32",
        "字面量带 f32 后缀".into(),
        one_line(&code32),
        ok,
        "f32 变体只换字面量后缀（发射规则一致）；实测 SIMD 收益 1.44×".into(),
    );

    // 4b2) Vector algebra: dot / norm (expanded only on concrete literals)
    let dv = himari_matlab::parse("decl { x : d; y : d; } dot([x, y], [x, y])").unwrap();
    let (_, dve) = dv.into_single();
    let mut venv = HashMap::new();
    venv.insert("x".to_string(), 3.0);
    venv.insert("y".to_string(), 4.0);
    let dvv = eval_value(&dve, &venv).unwrap().as_scalar().map(|c| c.re);
    let nv = himari_matlab::parse("decl { x : d; y : d; } norm([x, y])").unwrap();
    let (_, nve) = nv.into_single();
    let nvv = eval_value(&nve, &venv).unwrap().as_scalar().map(|c| c.re);
    let ok = dvv == Some(25.0) && nvv == Some(5.0);
    push(
        rows,
        "op-dot-norm",
        "dot=25；norm=5".into(),
        format!("{dvv:?} / {nvv:?}"),
        ok,
        "向量代数：dot 求和、norm 开方，都只在具体字面量上展开（形状编译期已知）".into(),
    );

    // 4b3) Horner: explicit polynomials convert automatically, compact spellings are left alone
    let hp = himari_matlab::parse("decl { x : d; a : d; b : d; } a * x ^ 3 + b * x").unwrap();
    let (_, hpe) = hp.into_single();
    // In the buildhelper lane Horner is a transform done **before emission**; the same path is
    // followed here
    let hornered = himari::horner_in(&hpe, "x").expect("显式多项式应可 Horner");
    let code = one_line(&himari::emit_block(&hornered));
    let compact = himari_matlab::parse("decl { u : d; } (u - 1) ^ 3").unwrap();
    let (_, ce) = compact.into_single();
    // A compact spelling must **not** be converted (converting makes it harder to read):
    // `horner_in` returns None
    let compact_untouched = himari::horner_in(&ce, "u").is_none();
    let ok = !code.contains("powi(3)") && code.contains("(a * x * x + b) * x") && compact_untouched;
    let note = format!(
        "显式多项式 c₀+c₁x+c₂x² 自动转 Horner（乘法 2n-1→n、无大幂）；紧凑 (u-1)^3 不动（{}）",
        if compact_untouched {
            "已验"
        } else {
            "被误转"
        }
    );
    push(rows, "op-horner", "幂次和 → Horner".into(), code, ok, note);

    // 4c) Linear solving: the resulting expression is still IR, and it can be evaluated and
    // differentiated
    let sol =
        himari_matlab::parse("decl { k1 : d; k2 : d; a : d; x : d; } solve(k1 * a - k2 * x, x)")
            .unwrap();
    let (_, sole) = sol.into_single();
    let mut senv = HashMap::new();
    for (k, v) in [("k1", 3.0), ("k2", 4.0), ("a", 2.0)] {
        senv.insert(k.to_string(), v);
    }
    let value = eval_value(&sole, &senv).unwrap().as_scalar().map(|c| c.re);
    let d = himari::simplify(&himari::diff(&sole, "a"));
    let dval = eval_value(&d, &senv).unwrap().as_scalar().map(|c| c.re);
    // Nonlinear must be an error (no silent wrong answer)
    let bad = himari_matlab::parse("decl { x : d; } solve(x * x - 1, x)");
    let ok = value == Some(1.5) && dval == Some(0.75) && bad.is_err();
    push(
        rows,
        "op-solve",
        "x = k1·a/k2 = 1.5；∂x/∂a = 0.75".into(),
        format!(
            "{value:?} / {dval:?}；非线性 {}",
            if bad.is_err() {
                "拒绝"
            } else {
                "被接受（错）"
            }
        ),
        ok,
        "solve(expr, x)：线性求解，解仍是 IR（可求值/求导/生成代码）；非线性明确拒绝".into(),
    );

    // 5) After expansion det is **differentiable** (FEM needs d(area)/dx)
    let f = himari_matlab::parse("decl { x : d; } det([x, 1; 2, x])").unwrap();
    let (_, fe) = f.into_single();
    let d = himari::simplify(&himari::diff(&fe, "x"));
    let mut env3 = HashMap::new();
    env3.insert("x".to_string(), 3.0);
    // det = x²-2 → derivative 2x = 6
    let dv = eval_value(&d, &env3).unwrap().as_scalar().map(|c| c.re);
    push(
        rows,
        "op-det-diff",
        "6（d(x²-2)/dx）".into(),
        format!("{dv:?}"),
        dv == Some(6.0),
        "det/trace 先在字面量上展开再微分：展开后就是普通可微表达式".into(),
    );
}
